const guardianAreas=['Mission District','Castro','SoMa','Noe Valley','Potrero Hill','Hayes Valley','Bernal Heights','Dogpatch','Inner Sunset','Marina'];
const guardianMedicines=[
 {id:'insulin',name:'Insulin Glargine',temp:'2–8°C'},
 {id:'semaglutide',name:'Semaglutide',temp:'2–8°C'},
 {id:'amoxicillin',name:'Amoxicillin Suspension',temp:'2–8°C'},
 {id:'epinephrine',name:'Epinephrine Auto-Injector',temp:'Room temperature'}
];
const guardianPharmacies=[
{id:1,name:'Mission Community Pharmacy',area:'Mission District',status:'OUTAGE',power:false,cooling:18,capacity:22,phone:'(415) 555-0101',stock:{insulin:18,semaglutide:11,amoxicillin:14,epinephrine:8}},
{id:2,name:'Castro Health Pharmacy',area:'Castro',status:'ONLINE',power:true,cooling:999,capacity:74,phone:'(415) 555-0102',stock:{insulin:42,semaglutide:20,amoxicillin:31,epinephrine:17}},
{id:3,name:'SoMa Care Rx',area:'SoMa',status:'ONLINE',power:true,cooling:999,capacity:61,phone:'(415) 555-0103',stock:{insulin:27,semaglutide:8,amoxicillin:46,epinephrine:29}},
{id:4,name:'Noe Valley Pharmacy',area:'Noe Valley',status:'GENERATOR',power:true,cooling:999,capacity:38,phone:'(415) 555-0104',stock:{insulin:12,semaglutide:15,amoxicillin:9,epinephrine:13}},
{id:5,name:'Potrero Wellness Rx',area:'Potrero Hill',status:'ONLINE',power:true,cooling:999,capacity:66,phone:'(415) 555-0105',stock:{insulin:24,semaglutide:12,amoxicillin:20,epinephrine:11}},
{id:6,name:'Hayes Valley Pharmacy',area:'Hayes Valley',status:'ONLINE',power:true,cooling:999,capacity:49,phone:'(415) 555-0106',stock:{insulin:16,semaglutide:26,amoxicillin:18,epinephrine:21}},
{id:7,name:'Bernal Family Drugs',area:'Bernal Heights',status:'ONLINE',power:true,cooling:999,capacity:57,phone:'(415) 555-0107',stock:{insulin:9,semaglutide:6,amoxicillin:25,epinephrine:15}},
{id:8,name:'Dogpatch Community Rx',area:'Dogpatch',status:'ONLINE',power:true,cooling:999,capacity:82,phone:'(415) 555-0108',stock:{insulin:31,semaglutide:17,amoxicillin:22,epinephrine:18}},
{id:9,name:'Sunset Care Pharmacy',area:'Inner Sunset',status:'OUTAGE',power:false,cooling:31,capacity:28,phone:'(415) 555-0109',stock:{insulin:14,semaglutide:9,amoxicillin:16,epinephrine:20}},
{id:10,name:'Marina Health Mart',area:'Marina',status:'ONLINE',power:true,cooling:999,capacity:70,phone:'(415) 555-0110',stock:{insulin:19,semaglutide:23,amoxicillin:12,epinephrine:24}}
];
const guardianCoords={'Mission District':[0,0],'Castro':[-1,1],'SoMa':[2,2],'Noe Valley':[-1,-2],'Potrero Hill':[2,-1],'Hayes Valley':[0,2],'Bernal Heights':[0,-3],'Dogpatch':[3,-1],'Inner Sunset':[-4,1],'Marina':[1,6]};
const DEMO_ORIGIN='Mission District';
function communityRoute(area,destination){if(area===destination)return{miles:0.5,minutes:4};const a=guardianCoords[area],b=guardianCoords[destination];if(!a||!b)return{miles:null,minutes:null};const d=Math.hypot(a[0]-b[0],a[1]-b[1]);return{miles:+(.55+d*.72).toFixed(1),minutes:Math.round(4+d*4.2)}}
function buildUnifiedFacilities(){return guardianPharmacies.map(p=>{const r=communityRoute(DEMO_ORIGIN,p.area);return{id:'g'+p.id,name:p.name,area:p.area,stock:{...p.stock},miles:r.miles,min:r.minutes,available:p.power,generator:p.status==='GENERATOR',power:p.power,capacityPercent:p.capacity,capacity:null,updated:'Synthetic snapshot',phone:p.phone,cooling:p.power?null:p.cooling}})}
let finderArea='Mission District',finderMedicine='insulin',guardianQuestion='',guardianAnswer='',guardianBusy=false,guardianError='';
function finderResults(){return facilities.filter(p=>p.power&&p.stock?.[finderMedicine]>0).map(p=>({...p,...communityRoute(finderArea,p.area)})).sort((a,b)=>a.minutes-b.minutes)}
function networkSummary(){return `<section class="community-banner"><div><span class="eyebrow">COMMUNITY + PHARMACY CONTINUITY</span><h2>One network. Two ways to keep care moving.</h2><p>User in the community, or coordinate an incident inside your pharmacy.</p></div><div class="actions"><a class="button primary" href="#find">User →</a><a class="button" href="#response">Manage an outage →</a></div></section>`}
function finderPage(){const results=finderResults(),best=results[0],med=guardianMedicines.find(m=>m.id===finderMedicine);return heading('COMMUNITY MEDICINE FINDER','Find the medicine you need.','Search the shared fictional pharmacy network by service area, stock, and power status.')+`<div class="card"><div class="finder-controls"><label class="fieldlabel">Your service area<select id="finder-area">${guardianAreas.map(a=>`<option ${a===finderArea?'selected':''}>${a}</option>`).join('')}</select></label><label class="fieldlabel">Medicine<select id="finder-medicine">${guardianMedicines.map(m=>`<option value="${m.id}" ${m.id===finderMedicine?'selected':''}>${m.name}</option>`).join('')}</select></label></div><p class="footnote">Synthetic stock and modeled travel times. Product names are search examples; verify exact formulation, availability, and instructions with the receiving pharmacy.</p></div><div class="cols full"><div class="card best-match"><span class="pill">CLOSEST POWERED MATCH · DEMO</span>${best?`<h2 class="full">${esc(best.name)}</h2><p class="subtitle">${esc(best.area)}</p><div class="number">${best.minutes} min <small>· ${best.miles.toFixed(1)} miles · Demo</small></div><div class="stock-highlight"><strong>${best.stock[finderMedicine]} synthetic units</strong><p>${esc(med.name)}</p></div><p class="footnote">Contact details from the supplied project use fictional 555 numbers. No real pharmacy availability is represented.</p><div class="actions full"><button data-community-details="${best.id}">View partner record</button><a class="button" href="#storage">Storage network →</a></div>`:'<div class="empty"><h2>No powered site with recorded stock</h2><p>Try another medicine or service area. Do not treat demo records as live supply.</p></div>'}</div><div class="card"><div class="sectiontop"><h2>Other nearby options</h2><span class="pill grey">${results.length} powered matches</span></div>${results.slice(1,5).map((p,i)=>`<div class="facility facility-head"><div><h3>${i+2}. ${esc(p.name)}</h3><p>${esc(p.area)} · ${p.stock[finderMedicine]} demo units</p></div><div><strong>${p.minutes} min</strong><p>${p.miles.toFixed(1)} miles</p></div></div>`).join('')}</div></div><div class="card full"><div class="sectiontop"><h2>Shared network status</h2><span class="pill grey">${facilities.length} demo pharmacies</span></div><div class="community-network">${facilities.map(p=>`<div><span class="pill ${p.power?'':'amber'}">${p.power?(p.generator?'GENERATOR':'POWERED'):'OUTAGE'}</span><h3>${esc(p.name)}</h3><p>${esc(p.area)}</p><small>${p.stock[finderMedicine]||0} demo units · ${p.capacityPercent}% relative receiving capacity</small></div>`).join('')}</div><div class="inline-note">Guardian’s receiving capacity is a percentage, not liters. Storage requests remain blocked until a pharmacist records available volume in liters and confirms the facility.</div></div><div class="inline-note full">Questions about medicine availability or outages? Open “Ask Guardian AI” in the corner.</div>`}

function bindCommunity(){document.querySelectorAll('[data-suitability]').forEach(c=>c.addEventListener('change',()=>{const f=facilities.find(x=>x.id===c.dataset.suitability);f.storageSuitable=c.checked;state.networkSuitability=state.networkSuitability||{};state.networkSuitability[f.id]=c.checked;log('Storage suitability review updated',f.name+' · Demo flag only.');render()}));document.querySelector('#finder-area')?.addEventListener('change',e=>{finderArea=e.target.value;guardianAnswer='';render()});document.querySelector('#finder-medicine')?.addEventListener('change',e=>{finderMedicine=e.target.value;guardianAnswer='';render()});document.querySelectorAll('[data-community-details]').forEach(b=>b.onclick=()=>{const p=facilities.find(x=>x.id===b.dataset.communityDetails);selectedStorage=p.id;capacityOnly=false;location.hash='storage'});document.querySelector('#guardian-chat-form')?.addEventListener('submit',async e=>{e.preventDefault();guardianQuestion=document.querySelector('#guardian-question').value.trim();if(!guardianQuestion)return;guardianBusy=true;guardianError='';render();try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:guardianQuestion,area:finderArea,medicine:finderMedicine,network:facilities})});const data=await r.json();if(!r.ok)throw Error(data.error||'Bedrock unavailable.');guardianAnswer=data.answer+'\n\nModel: '+data.model+' · Request: '+data.requestId;log('Guardian Bedrock answer generated','Community network question · '+data.requestId)}catch(e){guardianError=e.message}finally{guardianBusy=false;render()}});document.querySelectorAll('[data-volume]').forEach(b=>b.onclick=()=>{let f=facilities.find(x=>x.id===b.dataset.volume);form('Record available volume',`<p class="subtitle">${esc(f.name)} · Relative capacity: ${f.capacityPercent}%. Enter verified available liters; a percentage cannot be converted automatically.</p><label>Available storage (L)<input name="liters" required type="number" min="0" max="10000" step="0.1" value="${Number.isFinite(f.capacity)?f.capacity:''}"></label>`,d=>{state.networkVolumes=state.networkVolumes||{};state.networkVolumes[f.id]=Number(d.get('liters'));f.capacity=state.networkVolumes[f.id];log('Receiving volume recorded',f.name+' · '+f.capacity+' L · Manual demo record.');save()})})}
